package com.bank.format;

import java.util.logging.Logger;

public class ReferenceValidator {

    private static final Logger log = Logger.getLogger(ReferenceValidator.class.getName());

    public boolean isMatch(String s, String p) {
        int m = s.length(), n = p.length();
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[0][0] = true;                               // empty matches empty
        for (int j = 1; j <= n; j++) {                 // empty text vs patterns like a*b*
            if (p.charAt(j - 1) == '*' && j >= 2) {
                dp[0][j] = dp[0][j - 2];               // star takes zero occurrences
            }
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char pc = p.charAt(j - 1);
                if (pc == '*') {
                    boolean zero = (j >= 2) && dp[i][j - 2]; // zero of preceding
                    char prev = p.charAt(j - 2);
                    boolean many = (prev == '.' || prev == s.charAt(i - 1)) && dp[i - 1][j];
                    dp[i][j] = zero || many;
                } else {
                    boolean single = (pc == '.' || pc == s.charAt(i - 1));
                    dp[i][j] = single && dp[i - 1][j - 1];
                }
            }
        }
        boolean result = dp[m][n];
        log.info(() -> "isMatch(" + s + "," + p + ") = " + result);
        return result;
    }
}
