package com.bank.format;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class RegexMatchDemo {

    private static final Logger log = Logger.getLogger(RegexMatchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Reference Validator (Regex Matching)");
        ReferenceValidator validator = new ReferenceValidator();
        log.info("'aab' vs 'c*a*b' → " + validator.isMatch("aab", "c*a*b")); // true
        log.info("'mississippi' vs 'mis*is*p*.' → " +
                validator.isMatch("mississippi", "mis*is*p*."));              // false
    }
}
